/** Get the nth constituent type of the given type. */
def getTypeAt(typ: Type, index: Int): Option[Type] = {
  if (index < 0) return None
  val itr = typeIterator(typ).drop(index)
  if (itr.hasNext) Some(itr.next) else None
}


